/**
 * Offline receive/canonical-wire audit.
 *
 * <p>The audit reads one datagram at a time, frames every cleartext envelope, reconstructs packet
 * numbers, applies routing/authentication/key-epoch precedence, decodes frames through the retained
 * TLS-Attacker frame table, commits or rolls back whole packet transactions and finally reports the
 * canonical envelopes plus the committed snapshot state.
 */
public final class ReceiveAudit {

    static final long MAX62 = (1L << 62) - 1;
    static final String[] LVL = {"I", "H", "A"};
    static final byte[] VERSION = {0, 0, 0, 1};

    /* ================================ state holders ================================ */

    static final class Stream {
        long high;
        long sendMax;
        Long finalSize;
        Long reset;
        Long stop;
        boolean listed;
        final Store bytes = new Store();
    }

    static final class PeerCid {
        final byte[] cid;
        final byte[] token;
        PeerCid(byte[] cid, byte[] token) {
            this.cid = cid;
            this.token = token;
        }
    }

    /** Packet-local envelope framing record. */
    static final class Pkt {
        int event;
        int index;
        int offset;
        int end;
        boolean bad;
        int lvl;
        int width = 1;
        int phase;
        long raw;
        long pn = -1;
        long expected;
        byte[] dcid;
        byte[] scid;
        byte[] token;
        byte[] payload;
    }

    /** A packet transaction failure: closes the connection and rolls the packet back. */
    static final class Fail extends RuntimeException {
        final String code;
        final long offset;
        Fail(String code, long offset) {
            super(code);
            this.code = code;
            this.offset = offset;
        }
        @Override
        public synchronized Throwable fillInStackTrace() {
            return this;
        }
    }

    /** Truncated body marker; converted into FRAME_ENCODING_ERROR by the frame loop. */
    static final class Trunc extends RuntimeException {
        @Override
        public synchronized Throwable fillInStackTrace() {
            return this;
        }
    }

    /* ================================ mutable byte store ================================ */

    static final class Store {
        final TreeMap<Long, byte[]> map = new TreeMap<>();
        long unique;

        /** Merges adjacent/overlapping equal bytes; false when an overlap differs. */
        boolean put(long off, byte[] data, List<Runnable> journal) {
            if (data.length == 0) return true;
            long s = off;
            long e = off + data.length;
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<byte[]> oldVals = new ArrayList<>();
            HashSet<Long> taken = new HashSet<>();
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, byte[]> floor = map.floorEntry(s);
                if (floor != null && !taken.contains(floor.getKey())) {
                    long fs = floor.getKey();
                    long fe = fs + floor.getValue().length;
                    if (fe >= s) {
                        taken.add(fs);
                        oldKeys.add(fs);
                        oldVals.add(floor.getValue());
                        s = fs;
                        if (fe > e) e = fe;
                        progress = true;
                    }
                }
                Iterator<Map.Entry<Long, byte[]>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, byte[]> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (taken.add(start)) {
                        oldKeys.add(start);
                        oldVals.add(entry.getValue());
                        long end = start + entry.getValue().length;
                        if (end > e) e = end;
                        progress = true;
                    }
                }
            }
            for (int i = 0; i < oldKeys.size(); i++) {
                long xs = oldKeys.get(i);
                byte[] xd = oldVals.get(i);
                long xe = xs + xd.length;
                long os = Math.max(xs, off);
                long oe = Math.min(xe, e);
                if (os < oe) {
                    for (long k = os; k < oe; k++) {
                        if (xd[(int) (k - xs)] != data[(int) (k - off)]) return false;
                    }
                }
            }
            byte[] merged = new byte[(int) (e - s)];
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) {
                byte[] xd = oldVals.get(i);
                oldSum += xd.length;
                System.arraycopy(xd, 0, merged, (int) (oldKeys.get(i) - s), xd.length);
            }
            System.arraycopy(data, 0, merged, (int) (off - s), data.length);
            for (Long key : oldKeys) map.remove(key);
            map.put(s, merged);
            long delta = (e - s) - oldSum;
            unique += delta;
            final long ns = s;
            final long span = e - s;
            journal.add(
                    () -> {
                        map.remove(ns);
                        for (int i = 0; i < oldKeys.size(); i++) map.put(oldKeys.get(i), oldVals.get(i));
                        unique -= delta;
                        assertUnique(span);
                    });
            return true;
        }

        private void assertUnique(long span) {
            /* journal closure keeps the running byte count exact; no other effect */
        }

        long prefix() {
            byte[] first = map.get(0L);
            return first == null ? 0 : first.length;
        }

        byte[] prefixBytes() {
            byte[] first = map.get(0L);
            return first == null ? new byte[0] : first;
        }

        List<Object> ranges() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, byte[]> entry : map.entrySet()) {
                long start = entry.getKey();
                out.add(Arrays.asList(start, start + entry.getValue().length));
            }
            return out;
        }

        Store copy() {
            Store other = new Store();
            other.map.putAll(map);
            other.unique = unique;
            return other;
        }
    }

    /* ================================ merged pn/sequence intervals ================================ */

    static final class IntervalSet {
        final TreeMap<Long, Long> map = new TreeMap<>(); // start -> exclusive end
        long count;

        void add(long a, long b, List<Runnable> journal) {
            if (b <= a) return;
            long s = a;
            long e = b;
            ArrayList<Long> oldKeys = new ArrayList<>();
            ArrayList<Long> oldEnds = new ArrayList<>();
            HashSet<Long> taken = new HashSet<>();
            boolean progress = true;
            while (progress) {
                progress = false;
                Map.Entry<Long, Long> floor = map.floorEntry(s);
                if (floor != null && !taken.contains(floor.getKey())) {
                    if (floor.getValue() >= s) {
                        taken.add(floor.getKey());
                        oldKeys.add(floor.getKey());
                        oldEnds.add(floor.getValue());
                        s = floor.getKey();
                        if (floor.getValue() > e) e = floor.getValue();
                        progress = true;
                    }
                }
                Iterator<Map.Entry<Long, Long>> it = map.tailMap(s, true).entrySet().iterator();
                while (it.hasNext()) {
                    Map.Entry<Long, Long> entry = it.next();
                    long start = entry.getKey();
                    if (start > e) break;
                    if (taken.add(start)) {
                        oldKeys.add(start);
                        oldEnds.add(entry.getValue());
                        if (entry.getValue() > e) e = entry.getValue();
                        progress = true;
                    }
                }
            }
            long oldSum = 0;
            for (int i = 0; i < oldKeys.size(); i++) oldSum += oldEnds.get(i) - oldKeys.get(i);
            for (Long key : oldKeys) map.remove(key);
            map.put(s, e);
            long delta = (e - s) - oldSum;
            count += delta;
            final long ns = s;
            journal.add(
                    () -> {
                        map.remove(ns);
                        for (int i = 0; i < oldKeys.size(); i++) map.put(oldKeys.get(i), oldEnds.get(i));
                        count -= delta;
                    });
        }

        List<Object> intervals() {
            List<Object> out = new ArrayList<>();
            for (Map.Entry<Long, Long> entry : map.entrySet()) out.add(Arrays.asList(entry.getKey(), entry.getValue()));
            return out;
        }

        /** Number of merged disjoint intervals. */
        int size() {
            return map.size();
        }

        long prefix() {
            Long end = map.get(0L);
            return end == null ? 0 : end;
        }

        byte[] hashBytes() {
            ByteArrayOutputStream out = new ByteArrayOutputStream(16 * map.size());
            for (Map.Entry<Long, Long> entry : map.entrySet()) {
                writeBE(out, entry.getKey());
                writeBE(out, entry.getValue());
            }
            return out.toByteArray();
        }
    }

    static void writeBE(ByteArrayOutputStream out, long value) {
        for (int i = 56; i >= 0; i -= 8) out.write((int) (value >>> i) & 0xff);
    }

    /* ================================ cursor ================================ */

    static final class Cur {
        final byte[] b;
        int pos;
        Cur(byte[] b) {
            this.b = b;
        }

        int left() {
            return b.length - pos;
        }

        /** Header/ body varint, any (possibly overlong) width. */
        long varint() {
            if (pos >= b.length) throw new Trunc();
            int first = b[pos] & 0xff;
            int width = 1 << (first >> 6);
            if (left() < width) throw new Trunc();
            long value = first & 0x3f;
            for (int i = 1; i < width; i++) value = (value << 8) | (b[pos + i] & 0xff);
            pos += width;
            return value;
        }

        /** Frame type varint: must use the shortest encoding. */
        long type() {
            if (pos >= b.length) throw new Trunc();
            int first = b[pos] & 0xff;
            int width = 1 << (first >> 6);
            if (left() < width) throw new Trunc();
            long value = first & 0x3f;
            for (int i = 1; i < width; i++) value = (value << 8) | (b[pos + i] & 0xff);
            if (width != minWidth(value)) throw new Trunc();
            pos += width;
            return value;
        }

        int u8() {
            if (pos >= b.length) throw new Trunc();
            return b[pos++] & 0xff;
        }

        byte[] take(long n) {
            if (n < 0 || n > left()) throw new Trunc();
            byte[] out = Arrays.copyOfRange(b, pos, pos + (int) n);
            pos += (int) n;
            return out;
        }

        byte[] rest() {
            byte[] out = Arrays.copyOfRange(b, pos, b.length);
            pos = b.length;
            return out;
        }
    }

    static int minWidth(long value) {
        if (value < 64) return 1;
        if (value < 16384) return 2;
        if (value < (1L << 30)) return 4;
        return 8;
    }

    static byte[] vi(long value) {
        return VariableLengthIntegerEncoding.encodeVariableLengthInteger(value);
    }

    static void writeVar(ByteArrayOutputStream out, long value) {
        out.writeBytes(vi(value));
    }

    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long half = modulus >>> 1;
        long delta = Math.floorMod(raw - expected, modulus);
        long near = expected + delta;
        if (delta > half && near - modulus >= 0) return near - modulus;
        return near;
    }

    /* ================================ trace configuration ================================ */

    private long connLimit;
    private long streamLimit;
    private long clientBidiLimit;
    private long clientUniLimit;
    private int cidLimit;
    private long localBidi;
    private long localUni;
    private byte[][] localCids;
    private byte[] peerCid;
    private byte[] peerToken;

    /* ================================ committed connection state ================================ */

    private final boolean[] keys = {true, false, false};
    private final long[] largest = {-1, -1, -1};
    @SuppressWarnings("unchecked")
    private final HashSet<Long>[] seen = (HashSet<Long>[]) new HashSet<?>[3];

    private final TreeMap<Long, long[]> epochStats = new TreeMap<>(); // epoch -> min,max,count
    private long currentEpoch;

    private final HashMap<Long, Stream> streams = new HashMap<>();
    private final Store[] crypto = {new Store(), new Store(), new Store()};
    private final IntervalSet[] acks = {new IntervalSet(), new IntervalSet(), new IntervalSet()};
    private final long[][] ecn = new long[3][3];

    private final TreeMap<Long, PeerCid> peerObserved = new TreeMap<>();
    private final HashMap<String, Long> cidOwner = new HashMap<>();
    private final TreeSet<Long> peerActive = new TreeSet<>();
    private long retireThreshold;
    private final IntervalSet retiredLocal = new IntervalSet();

    private long openedBidi;
    private long openedUni;
    private long used;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;

    private boolean closed;
    private Map<String, Object> closedRow;

    private final ArrayList<Runnable> journal = new ArrayList<>();

    private final List<Object> packetRows = new ArrayList<>();
    private final List<Object> datagramRows = new ArrayList<>();
    private MessageDigest digest;

    /* ================================ entry point ================================ */

    public Map<String, Object> audit(Main.Trace trace) {
        for (int i = 0; i < 3; i++) seen[i] = new HashSet<>();
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
        connLimit = trace.connection;
        streamLimit = trace.stream;
        clientBidiLimit = trace.bidi;
        clientUniLimit = trace.uni;
        cidLimit = trace.cidLimit;
        localBidi = trace.localBidi;
        localUni = trace.localUni;
        localCids = trace.localCids.toArray(new byte[0][]);
        peerCid = trace.peerCid;
        peerToken = trace.peerToken;

        for (int level = 0; level < 3; level++) {
            long seed = trace.received[level];
            if (seed >= 0) {
                largest[level] = seed;
                seen[level].add(seed);
                if (level == 2) epochStats.put(0L, new long[] {seed, seed, 1});
            }
        }
        peerObserved.put(0L, new PeerCid(peerCid, peerToken));
        cidOwner.put(Main.hex(peerCid), 0L);
        peerActive.add(0L);

        for (int event = 0; event < trace.events.size(); event++) {
            Main.Event entry = trace.events.get(event);
            if (entry.keys != null) {
                if (!closed) applyKeys(entry.keys);
                continue;
            }
            datagram(event, entry.wire, entry.auth);
        }
        return result();
    }

    private void applyKeys(List<String> list) {
        Arrays.fill(keys, false);
        for (String name : list) {
            if (name.equals("I")) keys[0] = true;
            else if (name.equals("H")) keys[1] = true;
            else keys[2] = true;
        }
    }

    /* ================================ datagram framing ================================ */

    private void datagram(int event, byte[] wire, List<Long> auth) {
        ByteArrayOutputStream acceptedBytes = new ByteArrayOutputStream();
        int accepted = 0;
        int attempts = 0;
        int pos = 0;
        while (pos < wire.length) {
            Pkt pkt = header(wire, pos);
            pkt.event = event;
            pkt.index = attempts++;
            Long annotation = pkt.index < auth.size() ? auth.get(pkt.index) : null;
            process(pkt, annotation, acceptedBytes);
            if (pkt.bad) break;
            pos = pkt.end;
        }
        byte[] concat = acceptedBytes.toByteArray();
        datagramRows.add(
                Main.object(
                        "event",
                        (long) event,
                        "packets",
                        (long) attempts,
                        "accepted",
                        (long) accepted,
                        "bytes",
                        (long) concat.length,
                        "sha256",
                        sha(concat)));
    }

    private Pkt header(byte[] wire, int pos) {
        Pkt pkt = new Pkt();
        pkt.offset = pos;
        pkt.dcid = new byte[0];
        pkt.scid = new byte[0];
        pkt.token = new byte[0];
        pkt.payload = new byte[0];
        int first = wire[pos] & 0xff;
        pkt.bad = true;
        if ((first & 0x80) != 0) {
            int base = first & 0xfc;
            if (base != 0xc0 && base != 0xe0) return pkt;
            pkt.lvl = base == 0xc0 ? 0 : 1;
            pkt.width = (first & 3) + 1;
            Cur cur = new Cur(wire);
            cur.pos = pos + 1;
            try {
                byte[] version = cur.take(4);
                if (!Arrays.equals(version, VERSION)) return pkt;
                int dcidLength = cur.u8();
                if (dcidLength > 20) return pkt;
                pkt.dcid = cur.take(dcidLength);
                int scidLength = cur.u8();
                if (scidLength > 20) return pkt;
                pkt.scid = cur.take(scidLength);
                if (pkt.lvl == 0) {
                    long tokenLength = cur.varint();
                    if (tokenLength > cur.left()) return pkt;
                    pkt.token = cur.take(tokenLength);
                }
                long length = cur.varint();
                if (length < pkt.width) return pkt;
                long payloadStart = (long) cur.pos + pkt.width;
                long end = (long) cur.pos + length;
                if (end > wire.length) return pkt;
                pkt.raw = pnBytes(wire, cur.pos, pkt.width);
                cur.pos = (int) payloadStart;
                pkt.payload = cur.take(end - payloadStart);
                pkt.end = (int) end;
                pkt.bad = false;
            } catch (Trunc truncated) {
                pkt.bad = true;
            }
            return pkt;
        }
        if ((first & 0xc0) != 0x40 || (first & 0x18) != 0) return pkt;
        pkt.lvl = 2;
        pkt.phase = (first >> 2) & 1;
        pkt.width = (first & 3) + 1;
        int cidWidth = localCids[0].length;
        long need = (long) pos + 1 + cidWidth + pkt.width;
        if (need > wire.length) return pkt;
        Cur cur = new Cur(wire);
        cur.pos = pos + 1;
        pkt.dcid = cur.take(cidWidth);
        pkt.raw = pnBytes(wire, cur.pos, pkt.width);
        cur.pos += pkt.width;
        pkt.payload = cur.rest();
        pkt.end = wire.length;
        pkt.bad = false;
        return pkt;
    }

    private static long pnBytes(byte[] data, int pos, int width) {
        long value = 0;
        for (int i = 0; i < width; i++) value = (value << 8) | (data[pos + i] & 0xffL);
        return value;
    }

    /* ================================ packet pipeline ================================ */

    private void process(Pkt pkt, Long annotation, ByteArrayOutputStream datagramBytes) {
        if (pkt.bad) {
            packetRows.add(row(pkt, null, null, null, "BAD_HEADER", null));
            return;
        }
        int level = pkt.lvl;
        pkt.expected = largest[level] < 0 ? 0 : largest[level] + 1;
        pkt.pn = reconstruct(pkt.raw, pkt.width, pkt.expected);

        if (closed) {
            packetRows.add(row(pkt, LVL[level], pkt.pn, null, "CLOSED", null));
            return;
        }
        int destination = route(pkt.dcid);
        if (destination < 0) {
            packetRows.add(row(pkt, LVL[level], pkt.pn, null, "DROP_CID", null));
            return;
        }
        pkt.phase = destination; // reused only for A retirement checks? keep separate field below
        pkt.phase = (pkt.lvl == 2) ? pkt.phase : 0;
        if (!keys[level]) {
            packetRows.add(row(pkt, LVL[level], pkt.pn, null, "NO_KEY", null));
            return;
        }
        if (pkt.pn > MAX62) {
            packetRows.add(row(pkt, LVL[level], pkt.pn, null, "PN_RANGE", null));
            return;
        }
        Long generation = null;
        if (level == 2) {
            if (annotation == null || !generationAllowed(annotation, pkt.phase)) {
                packetRows.add(row(pkt, LVL[level], pkt.pn, null, "AUTH", null));
                return;
            }
            generation = annotation;
        } else {
            if (annotation == null || annotation != 0L) {
                packetRows.add(row(pkt, LVL[level], pkt.pn, null, "AUTH", null));
                return;
            }
        }
        Long epochOut = level == 2 ? generation : null;
        if (seen[level].contains(pkt.pn)) {
            packetRows.add(row(pkt, LVL[level], pkt.pn, epochOut, "DUPLICATE", null));
            return;
        }
        int destinationIndex = route(pkt.dcid);
        pkt.phase = pkt.phase; // no-op, destination kept below
        if (level == 2 && !orderOk(generation, pkt.pn)) {
            int mark = journal.size();
            close(pkt, 0, "KEY_UPDATE_ERROR");
            packetRows.add(row(pkt, LVL[level], pkt.pn, epochOut, "KEY_UPDATE_ERROR", null));
            undoTo(mark);
            return;
        }
        int mark = journal.size();
        try {
            int destinationSeq = destinationIndex;
            byte[] canonicalPayload = frames(pkt, level, destinationSeq);
            if (level == 2) acceptEpoch(generation, pkt.pn);
            seen[level].add(pkt.pn);
            if (pkt.pn > largest[level]) largest[level] = pkt.pn;
            byte[] envelope = envelope(pkt, canonicalPayload);
            journal.clear();
            String status = closeStatus;
            if (status != null) {
                close(pkt, closeOffset, status);
            }
            packetRows.add(row(pkt, LVL[level], pkt.pn, epochOut, status == null ? "OK" : status, sha(envelope)));
            datagramBytes.writeBytes(envelope);
        } catch (Fail failure) {
            undoTo(mark);
            close(pkt, failure.offset, failure.code);
            packetRows.add(row(pkt, LVL[level], pkt.pn, epochOut, failure.code, null));
        } finally {
            closeStatus = null;
            closeOffset = 0;
        }
    }

    private int route(byte[] dcid) {
        for (int i = 0; i < localCids.length; i++) {
            if (Arrays.equals(localCids[i], dcid) && !isRetired(i)) return i;
        }
        return -1;
    }

    private boolean isRetired(long sequence) {
        Map.Entry<Long, Long> floor = retiredLocal.map.floorEntry(sequence);
        return floor != null && floor.getValue() > sequence;
    }

    private boolean generationAllowed(long generation, int phase) {
        if (generation > MAX62) return false;
        if ((generation & 1) != phase) return false;
        return generation == currentEpoch
                || (generation == currentEpoch - 1 && currentEpoch >= 1)
                || (generation == currentEpoch + 1 && currentEpoch + 1 <= MAX62);
    }

    /** All PNs of a higher accepted epoch must exceed all PNs of a lower accepted epoch. */
    private boolean orderOk(long generation, long pn) {
        for (Map.Entry<Long, long[]> entry : epochStats.entrySet()) {
            long other = entry.getKey();
            if (other == generation) continue;
            long[] stats = entry.getValue();
            if (generation > other) {
                if (pn <= stats[1]) return false;
            } else {
                if (pn >= stats[0]) return false;
            }
        }
        return true;
    }

    private void acceptEpoch(long generation, long pn) {
        if (generation == currentEpoch + 1) {
            final long previous = currentEpoch;
            currentEpoch = generation;
            journal.add(() -> currentEpoch = previous);
        }
        long[] stats = epochStats.get(generation);
        if (stats == null) {
            epochStats.put(generation, new long[] {pn, pn, 1});
            journal.add(() -> epochStats.remove(generation));
        } else {
            final long oldMin = stats[0];
            final long oldMax = stats[1];
            final long oldCount = stats[2];
            if (pn < stats[0]) stats[0] = pn;
            if (pn > stats[1]) stats[1] = pn;
            stats[2] = oldCount + 1;
            journal.add(
                    () -> {
                        stats[0] = oldMin;
                        stats[1] = oldMax;
                        stats[2] = oldCount;
                    });
        }
    }

    private void close(Pkt pkt, long offset, String code) {
        closed = true;
        closedRow =
                Main.object(
                        "event",
                        (long) pkt.event,
                        "packet",
                        (long) pkt.index,
                        "offset",
                        offset,
                        "code",
                        code);
    }

    private void undoTo(int mark) {
        for (int i = journal.size() - 1; i >= mark; i--) journal.get(i).run();
        while (journal.size() > mark) journal.remove(journal.size() - 1);
    }

    private Map<String, Object> row(Pkt pkt, String level, Long pn, Long epoch, String status, String sha) {
        return Main.object(
                "event",
                (long) pkt.event,
                "packet",
                (long) pkt.index,
                "offset",
                (long) pkt.offset,
                "level",
                level,
                "pn",
                pn,
                "epoch",
                epoch,
                "status",
                status,
                "sha256",
                sha);
    }

    private String sha(byte[] bytes) {
        digest.reset();
        digest.update(bytes);
        return Main.hex(digest.digest());
    }

    /* ================================ canonical envelope ================================ */

    private byte[] envelope(Pkt pkt, byte[] payload) {
        int width = 1;
        for (; width <= 4; width++) {
            long mask = (1L << (8 * width)) - 1;
            if (reconstruct(pkt.pn & mask, width, pkt.expected) == pkt.pn) break;
        }
        if (width > 4) width = 4;
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        long low = pkt.pn;
        if (pkt.lvl != 2) {
            out.write((pkt.lvl == 0 ? 0xc0 : 0xe0) | (width - 1));
            out.writeBytes(VERSION);
            out.write(pkt.dcid.length);
            out.writeBytes(pkt.dcid);
            out.write(pkt.scid.length);
            out.writeBytes(pkt.scid);
            if (pkt.lvl == 0) {
                writeVar(out, pkt.token.length);
                out.writeBytes(pkt.token);
            }
            writeVar(out, (long) width + payload.length);
            for (int i = width - 1; i >= 0; i--) out.write((int) ((low >>> (8 * i)) & 0xff));
            out.writeBytes(payload);
        } else {
            out.write(0x40 | (pkt.phase << 2) | (width - 1));
            out.writeBytes(pkt.dcid);
            for (int i = width - 1; i >= 0; i--) out.write((int) ((low >>> (8 * i)) & 0xff));
            out.writeBytes(payload);
        }
        return out.toByteArray();
    }

    /* ================================ frame decoding ================================ */

    private String closeStatus;
    private long closeOffset;

    private byte[] frames(Pkt pkt, int level, int destinationSeq) {
        byte[] payload = pkt.payload;
        if (payload.length == 0) throw new Fail("FRAME_ENCODING_ERROR", 0);
        Cur cur = new Cur(payload);
        ByteArrayOutputStream out = new ByteArrayOutputStream(payload.length);
        while (cur.pos < payload.length) {
            long start = cur.pos;
            long type;
            try {
                type = cur.type();
            } catch (Trunc trunc) {
                throw new Fail("FRAME_ENCODING_ERROR", start);
            }
            if (!supported(type)) throw new Fail("FRAME_ENCODING_ERROR", start);
            checkSender(type, level, start);
            ByteArrayOutputStream frame = new ByteArrayOutputStream();
            frame.writeBytes(vi(type));
            try {
                decode(type, cur, frame, pkt, level, destinationSeq);
            } catch (Trunc trunc) {
                throw new Fail("FRAME_ENCODING_ERROR", start);
            }
            out.writeBytes(frame.toByteArray());
            if (type == 0x1c || type == 0x1d) {
                closeStatus = "PEER_CLOSE";
                closeOffset = start;
                return out.toByteArray();
            }
        }
        return out.toByteArray();
    }

    private static boolean supported(long type) {
        if (type >= 0x00 && type <= 0x1e) return true;
        return type == 0x30 || type == 0x31;
    }

    private static final long ALL_LEVELS = 0x00, 0x01, 0x02, 0x03, 0x06, 0x1c;

    private void checkSender(long type, int level, long start) {
        if (type == 0x07 || type == 0x1e) throw new Fail("PROTOCOL_VIOLATION", start);
        boolean applicationOnly =
                !(type == 0x00
                        || type == 0x01
                        || type == 0x02
                        || type == 0x03
                        || type == 0x06
                        || type == 0x1c);
        if (applicationOnly && level != 2) throw new Fail("PROTOCOL_VIOLATION", start);
    }

    private void decode(long type, Cur cur, ByteArrayOutputStream out, Pkt pkt, int level, int destinationSeq) {
        switch ((int) type) {
            case 0x00: // PADDING
            case 0x01: // PING
                return;
            case 0x02:
            case 0x03:
                ack(cur, out, level, type);
                return;
            case 0x04:
                resetStream(cur, out);
                return;
            case 0x05:
                stopSending(cur, out);
                return;
            case 0x06:
                crypto(cur, out, level);
                return;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                stream(type, cur, out);
                return;
            case 0x07:
                throw new Fail("PROTOCOL_VIOLATION", 0); // unreachable: rejected earlier
            case 0x10:
                maxData(cur, out);
                return;
            case 0x11:
                maxStreamData(cur, out);
                return;
            case 0x12:
                maxStreams(cur, out, true);
                return;
            case 0x13:
                maxStreams(cur, out, false);
                return;
            case 0x14:
                dataBlocked(cur, out);
                return;
            case 0x15:
                streamDataBlocked(cur, out);
                return;
            case 0x16:
                streamsBlocked(cur, out, true);
                return;
            case 0x17:
                streamsBlocked(cur, out, false);
                return;
            case 0x18:
                newConnectionId(cur, out, pkt);
                return;
            case 0x19:
                retireConnectionId(cur, out, destinationSeq);
                return;
            case 0x1a:
            case 0x1b:
                out.writeBytes(cur.take(8));
                return;
            case 0x1c:
                connectionClose(cur, out, true);
                return;
            case 0x1d:
                connectionClose(cur, out, false);
                return;
            case 0x1e:
                throw new Fail("PROTOCOL_VIOLATION", 0); // unreachable: rejected earlier
            case 0x30: {
                byte[] data = cur.rest();
                out.writeBytes(data);
                return;
            }
            case 0x31: {
                long length = cur.varint();
                byte[] data = cur.take(length);
                writeVar(out, data.length);
                out.writeBytes(data);
                return;
            }
            default:
                throw new Fail("FRAME_ENCODING_ERROR", 0);
        }
    }

    private void ack(Cur cur, ByteArrayOutputStream out, int level, long type) {
        long largestAck = cur.varint();
        long delay = cur.varint();
        long count = cur.varint();
        long first = cur.varint();
        writeVar(out, largestAck);
        writeVar(out, delay);
        writeVar(out, count);
        writeVar(out, first);
        if (first > largestAck) throw new Fail("FRAME_ENCODING_ERROR", 0);
        long low = largestAck - first;
        long spanStart = low;
        long spanEnd = largestAck + 1;
        IntervalSet pending = new IntervalSet();
        pending.add(spanStart, spanEnd, new ArrayList<>());
        for (long i = 1; i < count; i++) {
            long gap = cur.varint();
            writeVar(out, gap);
            if (low < gap + 2) throw new Fail("FRAME_ENCODING_ERROR", 0);
            long high = low - gap - 2;
            long range = cur.varint();
            writeVar(out, range);
            if (range > high) throw new Fail("FRAME_ENCODING_ERROR", 0);
            low = high - range;
            pending.add(low, high + 1, new ArrayList<>());
        }
        long ect0 = 0;
        long ect1 = 0;
        long ce = 0;
        if (type == 0x03) {
            ect0 = cur.varint();
            ect1 = cur.varint();
            ce = cur.varint();
            writeVar(out, ect0);
            writeVar(out, ect1);
            writeVar(out, ce);
        }
        // All arithmetic survived: commit the effects.
        IntervalSet committed = acks[level];
        long[] current = new long[] {spanStart, spanEnd};
        ArrayList<Runnable> pendingUndo = new ArrayList<>();
        committed.add(current[0], current[1], pendingUndo);
        for (long i = 1; i < count; i++) {}
        // rebuild ranges for commit (re-decode cheaply from the stored list)
        List<long[]> list = new ArrayList<>();
        list.add(new long[] {spanStart, spanEnd});
        // NOTE: gaps were consumed above; re-derive from the merged pending set.
        for (Map.Entry<Long, Long> entry : pending.map.entrySet()) {
            if (entry.getKey() == spanStart) continue;
            committed.add(entry.getKey(), entry.getValue(), pendingUndo);
        }
        journal.addAll(pendingUndo);
        if (type == 0x03) {
            for (int i = 0; i < 3; i++) {
                final long value = i == 0 ? ect0 : i == 1 ? ect1 : ce;
                if (value > ecn[level][i]) {
                    final long previous = ecn[level][i];
                    ecn[level][i] = value;
                    final int column = i;
                    journal.add(() -> ecn[level][column] = previous);
                }
            }
        }
    }
